```python
from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_balanced(parentheses: str) -> bool:
        stack = []
        for c in parentheses:
            if c == '(':
                stack.append(c)
            elif c == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    def find_group(parentheses: str, start_index: int, groups: List[str]) -> List[str]:
        if not parentheses:
            return groups if is_balanced(''.join(groups)) else []

        new_groups = []
        for i in range(start_index, len(parentheses)):
            if parentheses[i] == '(':
                new_groups = find_group(parentheses, i + 1, new_groups)
            if is_balanced(parentheses[:i+1]):
                new_groups.append(parentheses[:i + 1])
                find_group(parentheses[i + 1:], 0, new_groups)
        return groups + new_groups

    result = find_group(paren_string, 0, [])
    return [s for s in result if is_balanced(s)]
```

