from math import inf

def car_race_collision(n: int) -> int:
    # Define the cars moving right
    cars_left = {(0, speed) for speed in range(1, int(inf / n) + 1)}
    cars_right = {}

    # Main loop that simulate the cars moving on the infinite road
    while cars_left:
        # Remove cars from each set that would collide
        for speed in cars_right:
            if 0 < speed <= min(cars_left):
                cars_left.discard(speed)
                cars_right[speed] = max(cars_right.get(speed, 0) + 1, 1)
        # Remove cars from the right set that have crossed the infinitely long road
        for speed, count in cars_right.copy().items():
            if speed >= n:
                del cars_right[speed]

    return sum(cars_right.values())
