from typing import List, Union

def fib4(n: Union[int, List]):
    if isinstance(n, int) and n < 0:
        raise ValueError("n should be a non-negative integer, not a negative value.")
    if isinstance(n, int) and n == 0:
        return 0
    if isinstance(n, int) and (1 <= n <= 3):
        return 0
    fib4_list = [0, 0, 2]  # initialize the first 3 Fib4 numbers

    if isinstance(n, int):
        if n > 3:
            for _ in range(4, n + 1):
                fib4_list.append(fib4_list[-1] + fib4_list[-2])
            return fib4_list[n]
    else:  # if n is a list
        for i in range(len(n), len(fib4_list)):
            fib4_list.append(fib4_list[-1] + fib4_list[-2])
        return [fib4_list[i] for i in n]

```

