```python
from functools import reduce

def factorial(n):
    """Calculates n!"""
    return 1 if n <= 1 else n * factorial(n - 1)

def special_factorial(n):
    """The Brazilian factorial is defined as:
    brazilian_factorial(n) = n! * (n-1)! * (n-2)! * ... * 1!
    where n > 0

    For example:
    >>> special_factorial(4)
    288
    """

